const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const atlanta = ee.Geometry.Point([-84.3880, 33.7490]).buffer(15000); // 15km buffer for urban area
  const collectionId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
  const band = 'avg_rad';
  const scale = 1000;

  // 2. Data Acquisition & Check
  const july_col = ee.ImageCollection(collectionId)
    .filterDate('2013-07-01', '2013-07-31')
    .filterBounds(atlanta);

  const dec_col = ee.ImageCollection(collectionId)
    .filterDate('2013-12-01', '2013-12-31')
    .filterBounds(atlanta);

  const july_col_size = july_col.size().getInfo();
  const dec_col_size = dec_col.size().getInfo();

  if (july_col_size === 0 || dec_col_size === 0) {
    console.log(`July 2013 images found: ${july_col_size}`);
    console.log(`December 2013 images found: ${dec_col_size}`);
    console.log('C1: Empty Collection');
    return;
  }

  // 3. Processing
  const july_image = july_col.mean().select(band);
  const dec_image = dec_col.mean().select(band);

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const july_stats = july_image.reduceRegion({
    reducer: reducer,
    geometry: atlanta,
    scale: scale,
    maxPixels: 1e9
  });

  const dec_stats = dec_image.reduceRegion({
    reducer: reducer,
    geometry: atlanta,
    scale: scale,
    maxPixels: 1e9
  });

  // 4. Calculation & Validation
  const july_results = july_stats.getInfo();
  const dec_results = dec_stats.getInfo();

  if (!july_results || !dec_results || !july_results.avg_rad || !dec_results.avg_rad) {
    console.log('C3: Calculation Failure - could not retrieve statistics.');
    return;
  }

  if (july_results.avg_rad_count === 0 || dec_results.avg_rad_count === 0) {
      console.log(`July 2013 valid pixels: ${july_results.avg_rad_count}`);
      console.log(`December 2013 valid pixels: ${dec_results.avg_rad_count}`);
      console.log('C2: No Valid Pixels');
      return;
  }

  const july_mean = july_results.avg_rad;
  const dec_mean = dec_results.avg_rad;

  // 5. Final Answer
  console.log(`July 2013 Avg Radiance: ${july_mean.toFixed(2)} (Pixels: ${july_results.avg_rad_count})`);
  console.log(`December 2013 Avg Radiance: ${dec_mean.toFixed(2)} (Pixels: ${dec_results.avg_rad_count})`);

  if (dec_mean > july_mean) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.toString()}`);
    console.log('D');
});
